<template>
  <div class="col-12 col-sm-10 col-md-6 col-lg-4 col-xl-4">
    <div class="verifyPhonePage my-5 rounded-3 overflow-hidden shadow-sm bg-white">
      <img :src="code.logo" alt="SureBills" loading="lazy" class="d-block mx-auto" />
      <h1 class="d-block text-center text-body mb-3">
        {{ __('verification code has been sent to your mobile') }} <span dir="auto">({{ code.user_mobile }})</span>
        {{ __('and your email') }} <span dir="auto">({{ code.user_email }})</span>
      </h1>
      <h2 class="d-block text-center text-body mb-3">{{ __('this verification code will be expired after') }} {{ code.expires_after_in_minutes }} {{ __('minute') }} </h2>
      <div class="form-group mb-3">
        <input @keyup.enter="sendPinCode" type="tel" class="form-control rounded-3 shadow-none text-body text-center p-0" v-model="pin" :placeholder="__('verification code')" maxlength="4">
        <div v-if="error != null" class="invalid-pin text-center text-danger mt-1 d-block fs-6">{{ message }}</div>
      </div><!-- form-group -->
      
      <!-- <h4 class="d-block text-center text-body fs-6 mb-3">{{ __('didn’t receive verification code') }}</h4> -->
      <div class="didnt_get_pin text-center mb-3 fs-6">
        <div v-if="timerCount > 0">
          <span>{{ __('didn’t receive verification code') }}</span> 
          <span class="didnt_get_pin_seconds">{{ __('resend after') }} {{ timerCount}}  {{__('Second') }}</span>
        </div>
        <div v-else>
          {{ __('didn’t receive verification code') }} <a href="" @click.prevent="resendCode" >{{ __('resend again')}}</a>
        </div>
      </div><!-- didnt_get_pin -->
      <hr>
      <div class="d-flex justify-content-center">
        <button type="button" class="btn-primary w-100 d-flex align-items-center justify-content-center rounded-3 border-0 shadow-none"  @click="sendPinCode" :disabled="is_loading">
          <i v-if="is_loading" class="fad fa-spinner fa-spin"></i>
          <span v-if="is_loading">{{ __('Loading') }} ...</span>
          <span v-if="!is_loading">{{ __('Verify') }}</span>
        </button>
      </div><!-- d-flex  -->
    </div><!-- verifyPhonePage -->
  </div><!-- col-12 -->
</template>

<script>
    export default {
        props: ['code'],
        data() {
            return {
                timerCount: 60,
                pin: null,
                error: null,
                is_loading: false,
                message: null,
            }
        },
        watch: {
            timerCount: {
                handler(value) {
                    if (value > 0) {
                        setTimeout(() => {
                            this.timerCount--;
                        }, 1000);
                    }
                },
            },
          pin(num) {
              this.pin = num.replace(/([٠١٢٣٤٥٦٧٨٩])|([۰۱۲۳۴۵۶۷۸۹])/g, (m, $1, $2) => m.charCodeAt(0) - ($1 ? 1632 : 1776))
              this.pin = this.pin.replace(/[^\d.\d]/g,'')
          }
        },
        mounted() {
            this.timerCount = this.code.diff_in_sec
        },
        methods: {
            sendPinCode() {
                this.is_loading = true
                axios.post('/two/factor/auth',{
                    'pin': this.pin
                })
                .then(response => {
                    if(response.data.success){
                        window.location.reload(); 
                    }else{
                        this.error = true;
                        if(response.data.message)
                        {
                          this.message = response.data.message;
                        }
                    }
                });
                setTimeout(() => {
                    this.is_loading = false
                }, 1000);
            },     
            resendCode() {
                this.is_loading = true
                axios.post('/two/factor/auth/resend/code')
                .then(response => {
                  window.location.reload(); 
                });
                setTimeout(() => {
                    this.is_loading = false
                }, 1000);
            }
        }
    }
</script>

